17	export enum MessageBusType {
18	  TOOL_CONFIRMATION_REQUEST = 'tool-confirmation-request',
19	  TOOL_CONFIRMATION_RESPONSE = 'tool-confirmation-response',
20	  TOOL_POLICY_REJECTION = 'tool-policy-rejection',
21	  TOOL_EXECUTION_SUCCESS = 'tool-execution-success',
22	  TOOL_EXECUTION_FAILURE = 'tool-execution-failure',
23	  UPDATE_POLICY = 'update-policy',
24	  TOOL_CALLS_UPDATE = 'tool-calls-update',
25	  ASK_USER_REQUEST = 'ask-user-request',
26	  ASK_USER_RESPONSE = 'ask-user-response',
27	  SUBAGENT_ACTIVITY = 'subagent-activity',
28	}
29	
30	export interface ToolCallsUpdateMessage {
31	  type: MessageBusType.TOOL_CALLS_UPDATE;
32	  toolCalls: ToolCall[];
33	  schedulerId: string;
34	}
35	
36	export interface ToolConfirmationRequest {
37	  type: MessageBusType.TOOL_CONFIRMATION_REQUEST;
38	  toolCall: FunctionCall;
39	  correlationId: string;
40	  serverName?: string;
41	  /**
42	   * Optional tool annotations (e.g., readOnlyHint, destructiveHint) from MCP.
43	   */
44	  toolAnnotations?: Record<string, unknown>;
45	  /**
46	   * Optional subagent name, if this tool call was initiated by a subagent.
47	   */
48	  subagent?: string;
49	  /**
50	   * Optional rich details for the confirmation UI (diffs, counts, etc.)
51	   */
52	  details?: SerializableConfirmationDetails;
53	  /**
54	   * Optional decision to force for this tool call, bypassing the policy engine.
55	   */
56	  forcedDecision?: 'allow' | 'deny' | 'ask_user';
57	}
58	
59	export interface ToolConfirmationResponse {
60	  type: MessageBusType.TOOL_CONFIRMATION_RESPONSE;
61	  correlationId: string;
62	  confirmed: boolean;
63	  /**
64	   * The specific outcome selected by the user.
65	   *
66	   * TODO: Make required after migration.
67	   */
68	  outcome?: ToolConfirmationOutcome;
69	  /**
70	   * Optional payload (e.g., modified content for 'modify_with_editor').
71	   */
72	  payload?: ToolConfirmationPayload;
73	  /**
74	   * When true, indicates that policy decision was ASK_USER and the tool should
75	   * show its legacy confirmation UI instead of auto-proceeding.
76	   */
77	  requiresUserConfirmation?: boolean;
78	}
