33	/**
34	 * Helper to format the policy denial error.
35	 */
36	export function getPolicyDenialError(
37	  config: Config,
38	  rule?: PolicyRule,
39	): { errorMessage: string; errorType: ToolErrorType } {
40	  const denyMessage = rule?.denyMessage ? ` ${rule.denyMessage}` : '';
41	  return {
42	    errorMessage: `Tool execution denied by policy.${denyMessage}`,
43	    errorType: ToolErrorType.POLICY_VIOLATION,
44	  };
45	}
