183	/**
184	 * Handles policy updates for standard tools (Shell, Info, etc.), including
185	 * session-level and persistent approvals.
186	 */
187	async function handleStandardPolicyUpdate(
188	  tool: AnyDeclarativeTool,
189	  outcome: ToolConfirmationOutcome,
190	  confirmationDetails: SerializableConfirmationDetails | undefined,
191	  messageBus: MessageBus,
192	  persistScope?: 'workspace' | 'user',
193	  toolInvocation?: AnyToolInvocation,
194	  config?: Config,
195	): Promise<void> {
196	  if (
197	    outcome === ToolConfirmationOutcome.ProceedAlways ||
198	    outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave
199	  ) {
200	    const options: PolicyUpdateOptions =
201	      toolInvocation?.getPolicyUpdateOptions?.(outcome) || {};
202	
203	    if (!options.commandPrefix && confirmationDetails?.type === 'exec') {
204	      options.commandPrefix = confirmationDetails.rootCommands;
205	    } else if (!options.argsPattern && confirmationDetails?.type === 'edit') {
206	      const filePath = config
207	        ? makeRelative(confirmationDetails.filePath, config.getTargetDir())
208	        : confirmationDetails.filePath;
209	      options.argsPattern = buildFilePathArgsPattern(filePath);
210	    }
211	
212	    await messageBus.publish({
213	      type: MessageBusType.UPDATE_POLICY,
214	      toolName: tool.name,
215	      persist: outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave,
216	      persistScope,
217	      ...options,
218	    });
219	  }
220	}
