import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import * as path from 'node:path';
import { createPolicyUpdater } from './config.js';
import { PolicyEngine } from './policy-engine.js';
import { MessageBus } from '../confirmation-bus/message-bus.js';
import { MessageBusType } from '../confirmation-bus/types.js';
import { Storage } from '../config/storage.js';
import { ApprovalMode } from './types.js';
import toml from '@iarna/toml';
import { vol, fs as memfs } from 'memfs';

vi.mock('node:fs/promises', () => import('memfs').then((m) => m.fs.promises));
vi.mock('../config/storage.js');

describe('scratch modes', () => {
  let policyEngine: PolicyEngine;
  let messageBus: MessageBus;
  let mockStorage: Storage;
  const policyFile = '/mock/user/.gemini/policies/auto-saved.toml';

  beforeEach(() => {
    vi.useFakeTimers();
    vol.reset();
    policyEngine = new PolicyEngine({ rules: [], checkers: [] });
    messageBus = new MessageBus(policyEngine);
    mockStorage = new Storage('/mock/project');
    vi.spyOn(mockStorage, 'getAutoSavedPolicyPath').mockReturnValue(policyFile);
  });

  afterEach(() => {
    vi.restoreAllMocks();
    vi.useRealTimers();
  });

  it('writes modes array and updates in place', async () => {
    createPolicyUpdater(policyEngine, messageBus, mockStorage);
    memfs.mkdirSync(path.dirname(policyFile), { recursive: true });

    await messageBus.publish({
      type: MessageBusType.UPDATE_POLICY,
      toolName: 'test_tool',
      persist: true,
      modes: [ApprovalMode.DEFAULT, ApprovalMode.AUTO_EDIT, ApprovalMode.YOLO],
    });
    await vi.advanceTimersByTimeAsync(100);

    let content = memfs.readFileSync(policyFile, 'utf-8') as string;
    console.log('AFTER FIRST:\n', content);
    expect(content).toContain('modes = [ "default", "autoEdit", "yolo" ]');

    // Re-approve same tool in YOLO -> should update in place (one rule).
    await messageBus.publish({
      type: MessageBusType.UPDATE_POLICY,
      toolName: 'test_tool',
      persist: true,
      modes: [ApprovalMode.YOLO],
    });
    await vi.advanceTimersByTimeAsync(100);

    content = memfs.readFileSync(policyFile, 'utf-8') as string;
    console.log('AFTER SECOND:\n', content);
    const parsed = toml.parse(content) as { rule?: unknown[] };
    expect(parsed.rule).toHaveLength(1);
    expect(content).toContain('modes = [ "yolo" ]');
  });
});
